package com.tino.backend.messaging.adapter.out.persistence;

import com.tino.backend.messaging.application.port.out.*;
import com.tino.backend.messaging.domain.model.*;
import com.tino.backend.shared.kernel.BusinessId;
import java.time.*; import java.math.BigDecimal; import java.util.*;
import org.jooq.*; import org.jooq.impl.DSL;
import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;

@Repository
public class JooqMessagingRepository implements MessagingRepository {
    private static final Table<?> CUSTOMERS=t("customers"), CONSENTS=t("message_consents"), AUDIT=t("message_consent_audit"), MESSAGES=t("messages"), EVIDENCE=t("message_delivery_evidence"), OUTBOX=t("message_outbox");
    private static final Field<Long> CONSENT_VERSION=DSL.field(DSL.name("message_consents", "version"),Long.class);
    private static final Field<UUID> ID=f("id",UUID.class), BUSINESS_ID=f("business_id",UUID.class), CUSTOMER_ID=f("customer_id",UUID.class), MESSAGE_ID=f("message_id",UUID.class);
    private static final Field<String> CHANNEL=f("channel",String.class), PURPOSE=f("purpose",String.class), TEMPLATE=f("template",String.class), RECIPIENT_HASH=f("recipient_ref_hash",String.class), IDEMPOTENCY=f("idempotency_key",String.class), FINGERPRINT=f("request_fingerprint",String.class), STATUS=f("status",String.class), PROVIDER=f("provider",String.class), PROVIDER_MESSAGE_ID=f("provider_message_id",String.class), PROVIDER_EVENT_ID=f("provider_event_id",String.class), COMMAND=f("command_type",String.class), STATE=f("state",String.class), LAST_ERROR=f("last_error",String.class);
    private static final Field<Boolean> GRANTED=f("granted",Boolean.class); private static final Field<Long> VERSION=f("version",Long.class); private static final Field<Integer> ATTEMPTS=f("attempt_count",Integer.class); private static final Field<OffsetDateTime> UPDATED=f("updated_at",OffsetDateTime.class), CREATED=f("created_at",OffsetDateTime.class), AVAILABLE=f("available_at",OffsetDateTime.class), LOCKED=f("locked_at",OffsetDateTime.class), COMPLETED=f("completed_at",OffsetDateTime.class);
    private static final Field<BigDecimal> AMOUNT=f("amount",BigDecimal.class); private final DSLContext dsl;
    public JooqMessagingRepository(DSLContext dsl){this.dsl=dsl;}
    @Override public boolean customerExists(BusinessId b,UUID c){try{return dsl.selectOne().from(CUSTOMERS).where(BUSINESS_ID.eq(b.value()).and(ID.eq(c))).fetchOptional().isPresent();}catch(RuntimeException e){throw x(e);}}
    @Override public Optional<ConsentRecord> findConsent(BusinessId b,UUID c,MessageChannel ch,MessagePurpose p){try{return dsl.select(GRANTED,RECIPIENT_HASH,VERSION).from(CONSENTS).where(BUSINESS_ID.eq(b.value()).and(CUSTOMER_ID.eq(c)).and(CHANNEL.eq(ch.name())).and(PURPOSE.eq(p.name()))).fetchOptional().map(r->new ConsentRecord(r.get(GRANTED),r.get(RECIPIENT_HASH),r.get(VERSION)));}catch(RuntimeException e){throw x(e);}}
    @Override public ConsentRecord upsertConsent(BusinessId b,UUID c,MessageChannel ch,MessagePurpose p,boolean g,String h,Instant at){try{dsl.insertInto(CONSENTS).columns(BUSINESS_ID,CUSTOMER_ID,CHANNEL,PURPOSE,GRANTED,RECIPIENT_HASH,VERSION,UPDATED).values(b.value(),c,ch.name(),p.name(),g,h,0L,time(at)).onConflict(BUSINESS_ID,CUSTOMER_ID,CHANNEL,PURPOSE).doUpdate().set(GRANTED,g).set(RECIPIENT_HASH,h).set(VERSION,CONSENT_VERSION.add(1)).set(UPDATED,time(at)).execute();return findConsent(b,c,ch,p).orElseThrow();}catch(RuntimeException e){throw x(e);}}
    @Override public void insertConsentAudit(ConsentAudit a){try{dsl.insertInto(AUDIT).columns(ID,BUSINESS_ID,CUSTOMER_ID,CHANNEL,PURPOSE,GRANTED,RECIPIENT_HASH,f("actor_user_id",UUID.class),CREATED).values(a.id(),a.businessId().value(),a.customerId(),a.channel().name(),a.purpose().name(),a.granted(),a.recipientHash(),a.actorUserId(),time(a.createdAt())).execute();}catch(RuntimeException e){throw x(e);}}
    @Override public Optional<Message> find(BusinessId b,UUID id){try{return dsl.select(MESSAGES.fields()).from(MESSAGES).where(BUSINESS_ID.eq(b.value()).and(ID.eq(id))).fetchOptional().map(JooqMessagingRepository::message);}catch(RuntimeException e){throw x(e);}}
    @Override public Optional<Message> findByIdempotency(BusinessId b,String k){try{return dsl.select(MESSAGES.fields()).from(MESSAGES).where(BUSINESS_ID.eq(b.value()).and(IDEMPOTENCY.eq(k))).fetchOptional().map(JooqMessagingRepository::message);}catch(RuntimeException e){throw x(e);}}
    @Override public void insert(Message m){try{dsl.insertInto(MESSAGES).columns(ID,BUSINESS_ID,CUSTOMER_ID,CHANNEL,PURPOSE,TEMPLATE,RECIPIENT_HASH,IDEMPOTENCY,FINGERPRINT,STATUS,PROVIDER,PROVIDER_MESSAGE_ID,VERSION,CREATED,UPDATED).values(m.id(),m.businessId().value(),m.customerId(),m.channel().name(),m.purpose().name(),m.template().name(),m.recipientRefHash(),m.idempotencyKey(),m.requestFingerprint(),m.status().name(),m.provider(),m.providerMessageId(),m.version(),time(m.createdAt()),time(m.updatedAt())).execute();}catch(RuntimeException e){throw x(e);}}
    @Override public void enqueue(OutboxCommand c){try{dsl.insertInto(OUTBOX).columns(ID,BUSINESS_ID,MESSAGE_ID,COMMAND,STATE,ATTEMPTS,AVAILABLE,CREATED).values(c.id(),c.businessId().value(),c.messageId(),c.commandType(),c.state(),c.attemptCount(),time(c.availableAt()),time(c.createdAt())).execute();}catch(RuntimeException e){throw x(e);}}
    @Override public Optional<OutboxCommand> claimOutbox(BusinessId b,UUID mid,Instant now){try{var r=dsl.select(OUTBOX.fields()).from(OUTBOX).where(BUSINESS_ID.eq(b.value()).and(MESSAGE_ID.eq(mid)).and(STATE.eq("PENDING")).and(AVAILABLE.le(time(now)))).forUpdate().skipLocked().fetchOptional();if(r.isEmpty())return Optional.empty();var c=outbox(r.orElseThrow());dsl.update(OUTBOX).set(STATE,"PROCESSING").set(ATTEMPTS,c.attemptCount()+1).set(LOCKED,time(now)).where(ID.eq(c.id())).execute();dsl.update(MESSAGES).set(STATUS,"PROCESSING").set(VERSION,VERSION.add(1)).set(UPDATED,time(now)).where(BUSINESS_ID.eq(b.value()).and(ID.eq(mid))).execute();return Optional.of(new OutboxCommand(c.id(),c.businessId(),c.messageId(),c.commandType(),"PROCESSING",c.attemptCount()+1,c.availableAt(),c.createdAt()));}catch(RuntimeException e){throw x(e);}}
    @Override public void completeOutbox(BusinessId b,UUID id,Instant at){try{dsl.update(OUTBOX).set(STATE,"COMPLETED").set(COMPLETED,time(at)).where(BUSINESS_ID.eq(b.value()).and(ID.eq(id))).execute();}catch(RuntimeException e){throw x(e);}}
    @Override public void failOutbox(BusinessId b,UUID id,Instant at,String err,boolean deadLetter){try{dsl.update(OUTBOX).set(STATE,deadLetter?"FAILED":"PENDING").set(AVAILABLE,time(at)).set(LOCKED,(OffsetDateTime)null).set(LAST_ERROR,err).where(BUSINESS_ID.eq(b.value()).and(ID.eq(id))).execute();}catch(RuntimeException e){throw x(e);}}
    @Override @Transactional public Message applyDelivery(BusinessId b,UUID mid,String provider,String event,String providerMid,MessageStatus status,Instant at){try{var existing=dsl.select(MESSAGE_ID).from(EVIDENCE).where(PROVIDER.eq(provider).and(PROVIDER_EVENT_ID.eq(event))).fetchOptional();if(existing.isEmpty()){dsl.insertInto(EVIDENCE).columns(ID,BUSINESS_ID,MESSAGE_ID,PROVIDER,PROVIDER_EVENT_ID,PROVIDER_MESSAGE_ID,STATUS,CREATED).values(UUID.randomUUID(),b.value(),mid,provider,event,providerMid,status.name(),time(at)).execute();dsl.update(MESSAGES).set(STATUS,status.name()).set(PROVIDER_MESSAGE_ID,providerMid).set(VERSION,VERSION.add(1)).set(UPDATED,time(at)).where(BUSINESS_ID.eq(b.value()).and(ID.eq(mid))).execute();}return find(b,mid).orElseThrow();}catch(RuntimeException e){throw x(e);}}
    @Override @Transactional public Message applyFailure(BusinessId b,UUID mid,String provider,String event,String providerMid,boolean deadLetter,Instant at){try{var existing=dsl.select(MESSAGE_ID).from(EVIDENCE).where(PROVIDER.eq(provider).and(PROVIDER_EVENT_ID.eq(event))).fetchOptional();if(existing.isEmpty()){dsl.insertInto(EVIDENCE).columns(ID,BUSINESS_ID,MESSAGE_ID,PROVIDER,PROVIDER_EVENT_ID,PROVIDER_MESSAGE_ID,STATUS,CREATED).values(UUID.randomUUID(),b.value(),mid,provider,event,providerMid,"FAILED",time(at)).execute();dsl.update(MESSAGES).set(STATUS,deadLetter?"DEAD_LETTER":"FAILED").set(PROVIDER_MESSAGE_ID,providerMid).set(VERSION,VERSION.add(1)).set(UPDATED,time(at)).where(BUSINESS_ID.eq(b.value()).and(ID.eq(mid))).execute();}return find(b,mid).orElseThrow();}catch(RuntimeException e){throw x(e);}}
    private static Message message(org.jooq.Record r){return new Message(r.get(ID),new BusinessId(r.get(BUSINESS_ID)),r.get(CUSTOMER_ID),MessageChannel.valueOf(r.get(CHANNEL)),MessagePurpose.valueOf(r.get(PURPOSE)),MessageTemplate.valueOf(r.get(TEMPLATE)),r.get(RECIPIENT_HASH),r.get(IDEMPOTENCY),r.get(FINGERPRINT),MessageStatus.valueOf(r.get(STATUS)),r.get(PROVIDER),r.get(PROVIDER_MESSAGE_ID),r.get(VERSION),r.get(CREATED).toInstant(),r.get(UPDATED).toInstant());}
    private static OutboxCommand outbox(org.jooq.Record r){return new OutboxCommand(r.get(ID),new BusinessId(r.get(BUSINESS_ID)),r.get(MESSAGE_ID),r.get(COMMAND),r.get(STATE),r.get(ATTEMPTS),r.get(AVAILABLE).toInstant(),r.get(CREATED).toInstant());}
    private static OffsetDateTime time(Instant i){return i.atOffset(ZoneOffset.UTC);} private static Table<?> t(String n){return DSL.table(DSL.name("public",n));} private static <T> Field<T> f(String n,Class<T> c){return DSL.field(DSL.name(n),c);} private static MessagingPersistenceException x(RuntimeException e){if(e instanceof MessagingPersistenceException p)return p;return new MessagingPersistenceException(e);}
}
